namespace Jenin.FontAwesome.Blazor.Analyzers;

/// <summary>
/// The JFA1001 known-name source: canonical names plus Font Awesome aliases from the vendored
/// 7.3.1 metadata, generated by <c>eng/generate-analyzer-icon-names.ps1</c> into the embedded
/// <c>KnownIconNames.txt</c> (one name per line, bare and <c>fa-</c>-prefixed forms).
/// <c>KnownIconStyles.txt</c> carries <c>style:name</c> pairs for the code fix, and
/// <c>KnownIconAliases.txt</c> carries <c>alias=canonical</c> pairs.
/// </summary>
internal static class KnownIconNames {
    private static readonly Lazy<HashSet<string>> _names = new(() => LoadSet("KnownIconNames.txt"), isThreadSafe: true);
    private static readonly Lazy<HashSet<string>> _styles = new(() => LoadSet("KnownIconStyles.txt"), isThreadSafe: true);
    private static readonly Lazy<Dictionary<string, string>> _aliases = new(LoadAliases, isThreadSafe: true);

    public static bool Contains(string name) => _names.Value.Contains(name);

    public static bool SupportsStyle(string style, string name) =>
        _styles.Value.Contains(style.ToLowerInvariant() + ":" + name);

    public static string Canonicalize(string name) =>
        _aliases.Value.TryGetValue(name, out var canonical) ? canonical : name;

    private static HashSet<string> LoadSet(string resource) {
        var names = new HashSet<string>(StringComparer.Ordinal);
        foreach(var line in LoadLines(resource)) {
            names.Add(line);
        }

        return names;
    }

    private static Dictionary<string, string> LoadAliases() {
        var aliases = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach(var line in LoadLines("KnownIconAliases.txt")) {
            var separator = line.IndexOf('=');
            if(separator > 0) {
                aliases[line.Substring(0, separator)] = line.Substring(separator + 1);
            }
        }

        return aliases;
    }

    private static IEnumerable<string> LoadLines(string resource) {
        var assembly = typeof(KnownIconNames).GetTypeInfo().Assembly;
        using var stream = assembly.GetManifestResourceStream("Jenin.FontAwesome.Blazor.Analyzers." + resource);
        if(stream is null) {
            yield break;
        }

        using var reader = new StreamReader(stream);
        string? line;
        while((line = reader.ReadLine()) is not null) {
            if(line.Length > 0) {
                yield return line;
            }
        }
    }
}
